<header class="fixed top-0 left-72 right-0 h-20 bg-surface-container-lowest/90 backdrop-blur-xl shadow-[0_1px_8px_rgba(0,0,0,0.04)] z-40 flex items-center justify-between px-space-lg">
    <div class="flex items-center gap-space-md w-full max-w-xl">
        <div class="relative w-full flex items-center"><span class="material-symbols-outlined absolute left-space-md text-outline text-[20px]">search</span><input class="w-full pl-11 pr-24 py-2.5 rounded-xl bg-surface-container-low text-on-surface font-body-md text-body-md placeholder:text-outline focus:outline-none focus:bg-surface-container-lowest focus:shadow-[0_0_0_2px_#39b8fd] transition-all" placeholder="Tìm kiếm nhân viên, bảng lương, báo cáo (Ctrl + K)..." type="text" />
            <div class="absolute right-space-sm flex items-center gap-space-xs"><kbd class="px-1.5 py-0.5 rounded bg-surface text-outline font-label-sm text-label-sm shadow-[0_1px_2px_rgba(0,0,0,0.06)]">⌘K</kbd></div>
        </div>
    </div>
    <div class="flex items-center gap-space-md">
        <div class="flex items-center bg-surface-container-low p-1 rounded-xl"><span class="material-symbols-outlined text-outline text-[18px] ml-2">switch_account</span><select class="bg-transparent font-label-md text-label-md text-on-surface font-medium px-2 py-1.5 rounded-lg focus:outline-none cursor-pointer">
                <option value="employee">Nhân viên</option>
                <option value="deputy">Phó phòng</option>
                <option selected="" value="hr">Nhân sự HR</option>
                <option value="director">Giám đốc</option>
                <option value="admin">Quản trị viên Admin</option>
            </select></div>
        <div class="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-surface-container"><span class="w-2 h-2 rounded-full bg-tertiary-container animate-pulse"></span><span class="font-label-sm text-label-sm text-tertiary font-semibold uppercase tracking-wider">Online</span></div><button class="relative p-2.5 rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-colors"><span class="material-symbols-outlined text-[22px]">notifications</span><span class="absolute top-2 right-2 w-2 h-2 rounded-full bg-error"></span></button><button class="p-2.5 rounded-xl text-on-surface-variant hover:bg-surface-container hover:text-on-surface transition-colors"><span class="material-symbols-outlined text-[22px]">help_outline</span></button>
        <div class="h-7 w-px bg-surface-variant"></div>
