            <div class="w-8 h-8 rounded-full bg-primary flex items-center justify-center shadow-[0_2px_4px_rgba(0,35,111,0.2)]"><span class="material-symbols-outlined text-on-primary text-[18px]">person</span></div>
        </div>
    </div>
</header>